import{_ as a,o as c,c as o,a0 as r}from"./chunks/framework.CfecN1Ke.js";const m=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),t={name:"explanation/concepts.md"};function d(n,e,s,i,l,p){return c(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>The domain vocabulary, each term defined once. Field-level contracts live in <a href="./../reference/">Reference</a>.</p><h2 id="generator" tabindex="-1">Generator <a class="header-anchor" href="#generator" aria-label="Permalink to &quot;Generator&quot;">​</a></h2><p>A <code>cypera gen &lt;kind&gt;</code> verb: <code>crate-map</code>, <code>cli</code>, <code>config</code>, <code>api</code>. Each reads repo sources and emits markdown — stdout by default, <code>--out</code> to a file.</p><h2 id="cypera-toml" tabindex="-1"><code>cypera.toml</code> <a class="header-anchor" href="#cypera-toml" aria-label="Permalink to &quot;`cypera.toml`&quot;">​</a></h2><p>The per-repo contract discovered upward from <code>--repo</code>/cwd: layer overrides, curated struct lists, titles, markers, splices, the <code>[check]</code> profile. Every <code>gen-*.py</code> wrapper&#39;s hard-coded values belong here — the schema is <a href="./../reference/cypera-toml.html"><code>cypera.toml</code></a>.</p><h2 id="crate-map" tabindex="-1">Crate map <a class="header-anchor" href="#crate-map" aria-label="Permalink to &quot;Crate map&quot;">​</a></h2><p>The crate/layer/purpose table every repo&#39;s explanation carries: workspace members + globs → per-crate rows, layer guessed by naming convention (<code>-core</code>→domain, <code>-cli</code>→binary, bare→binary, else adapter) and overridable via <code>--layer</code> or <code>[crate_map.layers]</code>.</p><h2 id="marker-splice" tabindex="-1">Marker splice <a class="header-anchor" href="#marker-splice" aria-label="Permalink to &quot;Marker splice&quot;">​</a></h2><p><code>&lt;!-- crate-map --&gt;</code> in a host page (typically <code>explanation/architecture.md</code>): <code>--out</code> on a marker-bearing file replaces only the table rows after it — prose untouched. This is the <code>gen-crate-map.py</code> convention, kept.</p><h2 id="entry-scan" tabindex="-1">Entry scan <a class="header-anchor" href="#entry-scan" aria-label="Permalink to &quot;Entry scan&quot;">​</a></h2><p>The per-crate read of <code>src/lib.rs</code>/<code>main.rs</code>: <code>//!</code> inner doc → summary paragraph; top-level <code>mod</code>/<code>pub mod</code> → module list.</p><h2 id="config-scan" tabindex="-1">Config scan <a class="header-anchor" href="#config-scan" aria-label="Permalink to &quot;Config scan&quot;">​</a></h2><p><code>pub struct</code> doc comments → field tables. <code>[config.structs]</code> curates which structs render; <code>[config.types]</code> maps Rust types to prose vocabulary.</p><h2 id="cli-walk" tabindex="-1">CLI walk <a class="header-anchor" href="#cli-walk" aria-label="Permalink to &quot;CLI walk&quot;">​</a></h2><p><code>gen cli</code> recurses <code>&lt;bin&gt; --help</code> (or wraps <code>gen-cli-docs</code> clap-markdown via <code>--input</code>) into a reference page. clap is the source of truth — the page can never drift from <code>--help</code>.</p><h2 id="api-index" tabindex="-1">API index <a class="header-anchor" href="#api-index" aria-label="Permalink to &quot;API index&quot;">​</a></h2><p><code>gen api</code> runs <code>cargo doc --workspace --no-deps</code>, resolves the target dir via <code>cargo metadata</code> (<code>&lt;NAME&gt;_ROOT</code> env override), copies <code>&lt;target&gt;/doc</code> into <code>docs/public/api</code>, and writes a styled crate index — the <code>gen-api*.py</code> port.</p><h2 id="docs-contract-cypera-check" tabindex="-1">Docs contract (<code>cypera check</code>) <a class="header-anchor" href="#docs-contract-cypera-check" aria-label="Permalink to &quot;Docs contract (`cypera check`)&quot;">​</a></h2><p>The org docs rules — README shape, AGENTS.md sections, no CHANGELOG, no versions in prose, Diátaxis layout, <code>docs:check</code> script, generated-file freshness, content pages per <code>[check] profile</code> — enforced mechanically; <code>--json</code> for CI.</p>',20)])])}const u=a(t,[["render",d]]);export{m as __pageData,u as default};
